const assert = require('assert');
const getSetup = require('./support/setup');

const request = require('./support/client');

function uniqid() {
  return Math.random() * 10_000_000;
}

describe('.retry(count)', function () {
  let setup;
  let base;

  before(async () => {
    setup = await getSetup();
    base = setup.uri;
  });

  this.timeout(15_000);

  it('should not retry if passed "0"', (done) => {
    request
      .get(`${base}/error`)
      .retry(0)
      .end((error, res) => {
        try {
          assert(error, 'expected an error');
          assert.equal(
            undefined,
            error.retries,
            'expected an error without .retries'
          );
          assert.equal(500, error.status, 'expected an error status of 500');
          done();
        } catch (err) {
          done(err);
        }
      });
  });

  it('should not retry if passed an invalid number', (done) => {
    request
      .get(`${base}/error`)
      .retry(-2)
      .end((error, res) => {
        try {
          assert(error, 'expected an error');
          assert.equal(
            undefined,
            error.retries,
            'expected an error without .retries'
          );
          assert.equal(500, error.status, 'expected an error status of 500');
          done();
        } catch (err) {
          done(err);
        }
      });
  });

  it('should not retry if passed undefined', (done) => {
    request
      .get(`${base}/error`)
      .retry(undefined)
      .end((error, res) => {
        try {
          assert(error, 'expected an error');
          assert.equal(
            undefined,
            error.retries,
            'expected an error without .retries'
          );
          assert.equal(500, error.status, 'expected an error status of 500');
          done();
        } catch (err) {
          done(err);
        }
