          assert.equal(500, error.status, 'expected an error status of 500');
          done();
        } catch (err) {
          done(err);
        }
      });
  });

  it('should handle successful request after repeat attempt from server error', (done) => {
    request
      .get(`${base}/error/ok/${uniqid()}`)
